import { useState } from 'react';

type Tier = {
  title: string;
  price: number;
  features: string[];
  buttonText: string;
};

const tiers: Tier[] = [
  { title: 'Basic', price: 9.99, features: ['1GB Storage', '2 Users'], buttonText: 'Get Started' },
  { title: 'Premium', price: 14.99, features: ['5GB Storage', '5 Users', 'Advanced Features'], buttonText: 'Upgrade Now' },
  { title: 'Enterprise', price: 39.99, features: ['Unlimited Storage', 'Unlimited Users', 'Custom Domain', 'Advanced Security'], buttonText: 'Contact Us' },
];

function PricingPage() {
  const [selectedTier, setSelectedTier] = useState<Tier | null>(null);

  return (
    <div className="flex flex-col items-center justify-center min-h-screen bg-gray-100 p-8">
      <h1 className="text-4xl font-bold text-center mb-6">Choose Your Plan</h1>
      <div className="grid grid-cols-3 gap-4">
        {tiers.map(tier => (
          <div key={tier.title} onClick={() => setSelectedTier(tier)} className="bg-white rounded shadow px-6 py-4 border border-gray-200 hover:bg-gray-200 cursor-pointer">
            <h2 className="text-lg font-medium mb-2">{tier.title}</h2>
            <p className="text-gray-700 leading-normal mb-4">${tier.price}</p>
            <ul className="list-disc pl-4">
              {tier.features.map(feature => (
                <li key={feature}>{feature}</li>
              ))}
            </ul>
            <button className="inline-flex items-center justify-center px-4 py-2 mt-4 bg-blue-500 text-white rounded hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 dark:bg-blue-700 dark:text-white dark:hover:bg-blue-800">
              {selectedTier === tier ? selectedTier.buttonText : tier.buttonText}
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
