import { useState } from 'react';

const PricingPage = () => {
  const [selectedTier, setSelectedTier] = useState('basic');

  return (
    <div className="bg-white">
      <header className="bg-blue-500 text-white p-4 flex justify-center items-center">
        <h1>Pricing</h1>
      </header>
      <main className="mx-auto max-w-3xl py-8">
        <section className="mb-12">
          <h2>Tier {selectedTier.toUpperCase()}</h2>
          <p className="text-gray-600">Starting at $<span className="font-bold">{getPrice(selectedTier)}</span></p>
          <ul className="list-disc ml-8">
            {getFeatures(selectedTier)}
          </ul>
          <button
            onClick={() => setSelectedTier(tier === 'premium' ? 'free' : 'premium')}
            className={`rounded-md bg-${tier === 'premium' ? 'blue' : 'green'} px-4 py-2 text-sm font-medium uppercase ${tier === 'premium' && 'hover:bg-gray-300'} ${
              selectedTier === tier ? 'opacity-75' : ''
            }`}
          >
            Upgrade to {tier.toUpperCase()}
          </button>
        </section>
      </main>
    </div>
  );
};

function getPrice(tier: string) {
  switch (tier) {
    case 'basic':
      return '$9.99';
    case 'premium':
      return '$19.99';
    case 'free':
      return '$0';
    default:
      throw new Error(`Unknown tier: ${tier}`);
  }
}

function getFeatures(tier: string) {
  switch (tier) {
    case 'basic':
      return ['Basic features', 'No advanced features'];
    case 'premium':
      return ['Advanced features', 'Premium support'];
    case 'free':
      return ['Free features'];
    default:
      throw new Error(`Unknown tier: ${tier}`);
  }
}

export default App;
