import { useState } from 'react';

export const App = () => {
  const [activeTier, setActiveTier] = useState(1);

  return (
    <div className="flex flex-col items-center justify-center h-screen bg-gray-100">
      <h1 className="text-4xl font-bold text-center mb-8">Choose your plan</h1>
      <div className="grid grid-cols-3 gap-6">
        {[1, 2, 3].map(tier => (
          <div key={tier} className={`bg-white shadow-lg rounded-lg p-6 flex flex-col items-center ${tier === activeTier ? 'border-b-2 border-blue-500' : ''}`}>
            <h2 className="text-2xl font-semibold">{tier === 1 ? 'Basic' : tier === 2 ? 'Standard' : 'Premium'}</h2>
            <p className="mt-4 text-xl">{tier === 1 ? '$9.99/month' : tier === 2 ? '$19.99/month' : '$29.99/month'}</p>
            <ul className="list-disc mt-4">
              {tier === 1 ? [
                'Access to all services',
                'Free trial for 1 month',
                'No ads'
              ] : tier === 2 ? [
                'All tiers included',
                'Early access to new features',
                'Priority support'
              ] : [
                'All tiers included',
                'Customization options',
                'Unlimited bandwidth'
              ]}
